.popout {
	--popout-highlight: rgba(255, 255, 255, 0.06);
	--popout-edge: rgba(0, 0, 0, 0.35);
	--popout-shadow: rgba(0, 0, 0, 0.25);

	pointer-events: auto;
	transition: none;
	-webkit-app-region: no-drag;
	filter: drop-shadow(0 2px 0 var(--popout-edge)) drop-shadow(0 4px 8px var(--popout-shadow))
		drop-shadow(0 12px 24px rgba(0, 0, 0, 0.15));
}

:global(.theme-light) .popout {
	--popout-highlight: rgba(255, 255, 255, 0.4);
	--popout-edge: rgba(0, 0, 0, 0.12);
	--popout-shadow: rgba(0, 0, 0, 0.1);
}

.popouts {
	background: none;
	inset: 0;
	pointer-events: none;
	position: fixed;
	z-index: var(--z-index-popout);
}

:global(html.platform-native:not(.platform-macos)) .popouts {
	top: var(--native-titlebar-height);
}

.backdrop {
	position: absolute;
	inset: 0;
	background: transparent;
	pointer-events: auto;
	z-index: -1;
}

.triggerWrapper {
	display: inline-flex;
}
