	.mainContent {
		--voice-call-horizontal-padding: 1rem;
		padding-left: 1rem;
		padding-right: 1rem;
		justify-content: flex-start;
		align-items: stretch;
		gap: 0.5rem;
	}

	.focusLayoutMain {
		padding-top: 0;
		padding-bottom: 0;
	}

	.focusLayoutMain .lkParticipantTile {
		max-width: 100%;
	}

	.focusMiniGrid {
		--focus-mini-tile-size: clamp(var(--focus-mini-tile-min-width), 24vw, var(--focus-mini-tile-max-width));
		--focus-mini-grid-gap: 0.5rem;
	}

	.focusMiniGridTile {
		max-width: var(--focus-mini-tile-max-width);
	}

	.gridLayoutWrapper {
		padding-top: 0;
		padding-bottom: 0;
	}

	.focusLayoutContent {
		--carousel-row-height: 140px;
		--content-padding: 1.5rem;
		--focus-mini-row-reserved-height: 132px;
	}

	.carouselToggleWrap {
		margin-top: 0.5rem;
	}

	.voiceRoot {
		--voice-hud-opacity: 1;
		--voice-hud-pointer-events: auto;
	}

	.controlBarContainer {
		--voice-control-horizontal-padding: 1rem;
		--voice-control-top-padding: 1.25rem;
		--voice-control-bottom-padding: calc(1rem + env(safe-area-inset-bottom, 0px));
	}

	.fullscreenButtonWrap {
		bottom: calc(1.5rem + env(safe-area-inset-bottom, 0px));
		right: 1rem;
	}
}

.screenshareGridLayout {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 100%;
	height: 100%;
}

.screenshareGridLayout .lkParticipantTile {
	width: 100%;
	height: 100%;
	aspect-ratio: 16 / 9;
}

.root {
	display: grid;
	grid-template-rows: auto minmax(0, 1fr) auto;
	grid-template-areas:
		'header'
		'main'
		'footer';
	height: 100%;
	width: 100%;
	background-color: #000;
}

.chrome {
	grid-area: header;
	position: relative;
	z-index: 20;
	display: flex;
	height: 64px;
	align-items: center;
	justify-content: space-between;
	background: transparent;
	padding-left: 1rem;
	padding-right: 1rem;
	border-top: none;
	box-shadow: none;
}

.chrome::before {
	content: '';
	position: absolute;
	inset: 0;
	background: var(--voice-header-gradient);
	pointer-events: none;
	z-index: -1;
}

.chromeMobile {
	height: 56px;
}

.channelInfoContainer {
	display: flex;
	align-items: center;
	gap: 0.75rem;
}

.backButton {
	display: flex;
	height: 32px;
	width: 32px;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border-radius: 6px;
	background-color: var(--background-modifier-hover);
	color: var(--text-primary);
	transition-duration: 150ms;
	transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
	cursor: pointer;
}

.backButton:hover {
	background-color: var(--background-modifier-selected);
}

.backButtonMobileOnly {
	display: none;
}

@media (max-width: 768px) {
	.backButtonDesktopOnly {
		display: none;
	}

	.backButtonMobileOnly {
		display: flex;
	}
}

.channelIconContainer {
	display: flex;
	height: 32px;
	width: 32px;
	align-items: center;
	justify-content: center;
}

.channelTextContainer {
	display: flex;
	flex-direction: column;
}

.channelName {
	font-weight: 600;
	color: var(--text-primary);
}

.participantCount {
	color: var(--text-secondary);
	font-size: 0.75rem;
	line-height: 1rem;
}

.controlsContainer {
	display: flex;
	align-items: center;
	gap: 0.25rem;
}

.connectionStatusContainer {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	border-radius: 6px;
	padding-left: 0.75rem;
	padding-right: 0.75rem;
	padding-top: 0.25rem;
	padding-bottom: 0.25rem;
	font-weight: 600;
	font-size: 0.75rem;
	line-height: 1rem;
}

.statusConnecting {
	background-color: var(--voice-status-warning-bg);
	color: var(--voice-status-warning);
}

.statusReconnecting {
	background-color: var(--voice-status-warning-bg);
	color: var(--voice-status-warning);
}

.statusDisconnected {
	background-color: var(--voice-status-danger-bg);
	color: var(--voice-status-danger);
}

.statusConnected {
	background-color: var(--voice-status-success-bg);
	color: var(--voice-status-success);
}

.connectionStatusDot {
	height: 8px;
	width: 8px;
	border-radius: 9999px;
	background-color: currentColor;
	animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes pulse {
	0%,
	100% {
		opacity: 1;
	}
	50% {
		opacity: 0.5;
	}
}

.headerButton {
	display: flex;
	height: 32px;
	width: 32px;
	align-items: center;
	justify-content: center;
	border-radius: 6px;
	color: var(--text-primary);
	transition-duration: 150ms;
	transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
	cursor: pointer;
}

.headerButton:hover {
	background-color: var(--background-modifier-selected);
}

.headerButtonActive {
	background-color: var(--background-modifier-selected);
}

.mainContent {
	grid-area: main;
	position: relative;
	display: flex;
	flex-direction: column;
	justify-content: center;
	align-items: center;
	height: 100%;
	overflow-x: hidden;
	overflow-y: hidden;
	--voice-call-horizontal-padding: clamp(1rem, 8vw, 14rem);
	padding-left: var(--voice-call-horizontal-padding);
	padding-right: var(--voice-call-horizontal-padding);
	min-height: 0;
	min-width: 0;
	container-type: size;
}

.mainContentFocusFullscreen {
	--voice-call-horizontal-padding: 0;
	position: relative;
	inset: auto;
	height: 100%;
	z-index: 1;
}

.controlBarContainer {
	grid-area: footer;
	position: relative;
	z-index: 30;
	display: flex;
	justify-content: center;
	background: transparent;
	--voice-control-horizontal-padding: 1.5rem;
	--voice-control-top-padding: 1.75rem;
	--voice-control-bottom-padding: calc(1.25rem + env(safe-area-inset-bottom, 0px));
	padding-left: var(--voice-control-horizontal-padding);
	padding-right: var(--voice-control-horizontal-padding);
	padding-top: var(--voice-control-top-padding);
	padding-bottom: var(--voice-control-bottom-padding);
	pointer-events: none;
}

.controlBarContainer::before {
	content: '';
	position: absolute;
	top: 0;
	left: 0;
	right: 0;
	height: 64px;
	background: var(--voice-footer-gradient);
	pointer-events: none;
	transform: translateY(-100%);
}

.controlBarContainer > * {
	pointer-events: auto;
}

.fullscreenButtonWrap {
	position: absolute;
	right: clamp(1rem, 2vw, 2rem);
	bottom: calc(1.75rem + env(safe-area-inset-bottom, 0px));
	z-index: 35;
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: auto;
}

.fullscreenButtonWrap button {
	background-color: var(--voice-surface-4);
	color: var(--voice-text-strong);
}

.fullscreenButtonWrap button:hover {
	background-color: var(--voice-surface-5);
}

.srOnly {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border-width: 0;
}

.iconMedium {
	height: 20px;
	width: 20px;
}

.iconLarge {
	height: 24px;
	width: 24px;
}

.channelIconStyling {
	height: 20px;
	width: 20px;
	color: var(--text-primary);
}

.scrollerFullWidth {
	width: 100%;
}

.carouselToggleFocusRing {
	border-radius: 9999px;
}

.voiceCallSheetContent {
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.voiceCallSheetCompact {
	width: 100%;
	min-height: 0;
	border-radius: var(--radius-lg);
	overflow: hidden;
}

.streamFocusInfo {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	min-width: 0;
	flex-shrink: 1;
	overflow: visible;
}

.streamFocusTopicDivider {
	margin-left: 0 !important;
	margin-right: 0 !important;
	opacity: 0.5;
}

.streamFocusStreamer {
	display: flex;
	align-items: center;
	gap: 0.375rem;
	min-width: 0;
	flex-shrink: 1;
	overflow: visible;
}

.streamFocusStreamerName {
	font-size: 0.875rem;
	line-height: 1.25rem;
	font-weight: 500;
	color: var(--voice-call-header-text, var(--text-primary));
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
}

.streamFocusSpectators {
	display: flex;
	align-items: center;
	gap: 0.25rem;
	flex-shrink: 0;
	cursor: pointer;
}

.headerStreamInfo {
	display: flex;
	align-items: center;
	gap: 8px;
	flex-shrink: 0;
	margin-right: 4px;
}
