.qrContainer {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 1.25rem;
	margin-bottom: var(--spacing-4);
}

.instructionsContainer {
	display: flex;
	flex-direction: column;
	gap: 0.5rem;
}

.secretText {
	user-select: text;
	-webkit-user-select: text;
	font-size: 0.875rem;
	color: var(--text-primary-muted);
	font-family: var(--font-mono);
}
