.container {
	position: relative;
	flex-shrink: 0;
}

.statusDot {
	pointer-events: auto;
	position: absolute;
}

.iconImageContainer {
	position: absolute;
	inset: 0;
	border-radius: 9999px;
	background-color: var(--background-secondary);
	background-position: center;
	background-size: cover;
}

.defaultIconContainer {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border-radius: 9999px;
	background-color: var(--background-secondary);
}

.defaultIcon {
	color: white;
}

.avatarPosition {
	position: absolute;
	border-radius: 9999px;
}

.avatarWrapper {
	position: absolute;
	border-radius: 9999px;
}

.multiAvatarContainer {
	position: relative;
	flex-shrink: 0;
	border-radius: 9999px;
}
