.nagbarList {
	display: flex;
	flex-direction: column;
	gap: 0.75rem;
}

.nagbarItem {
	display: flex;
	align-items: center;
	justify-content: space-between;
}

.nagbarInfo {
	display: flex;
	flex-direction: column;
}

.nagbarLabel {
	font-size: 0.875rem;
}

.nagbarStatus {
	color: var(--text-tertiary);
	font-size: 0.75rem;
}

.buttonGroup {
	display: flex;
	gap: 0.5rem;
}

.footer {
	display: flex;
	flex-wrap: wrap;
}

.footer > * {
	flex: 1;
	min-width: fit-content;
}
