.videoOverlay {
	position: absolute;
	inset: 0;
	display: flex;
	cursor: pointer;
	align-items: center;
	justify-content: center;
	border: none;
	background: transparent;
	padding: 0;
	outline: none;
	width: 100%;
	height: 100%;
	max-width: 100%;
}

.playButtonWrapper {
	position: absolute;
	top: 50%;
	left: 50%;
	transform: translate(-50%, -50%);
	display: flex;
	align-items: center;
	justify-content: center;
	pointer-events: auto;
	cursor: pointer;
	z-index: 1;
}

.thumbnailPlaceholder {
	position: absolute;
	inset: 0;
	height: 100%;
	width: 100%;
	max-width: 100%;
	object-fit: cover;
}

.blurContainer {
	display: flex;
	flex-direction: column;
}

.blurContent {
	display: grid;
	user-select: none;
	-webkit-user-select: none;
	overflow: hidden;
	border-radius: var(--media-border-radius, 0);
}

.blurInner {
	position: relative;
	display: flex;
	height: 100%;
	width: 100%;
	align-items: center;
	justify-content: center;
	background: var(--background-primary);
}

.blurThumbnail {
	position: absolute;
	inset: 0;
	height: 100%;
	width: 100%;
	object-fit: cover;
}

.mediaContainer {
	display: grid;
	margin: 0;
	user-select: none;
	-webkit-user-select: none;
	overflow: hidden;
	border: 0;
	padding: 0;
	cursor: pointer;
	border-radius: var(--media-border-radius, 0);
}

.mobileContainer {
	position: relative;
	height: 100%;
	width: 100%;
	background: var(--background-primary);
	border-radius: var(--media-border-radius, 0);
	overflow: hidden;
}

.videoPlayerWrapper {
	position: relative;
	width: 100%;
	height: 100%;
}

.videoPlayerBlock {
	display: block;
	width: 100%;
	border-radius: var(--media-border-radius, 0);
	overflow: hidden;
}

.videoPlayerFill {
	width: 100%;
	height: 100%;
	border-radius: 0;
}

.inlineVideo {
	position: absolute;
	inset: 0;
	width: 100%;
	height: 100%;
	object-fit: contain;
	background-color: #000;
}

.inlineMuteButton {
	position: absolute;
	bottom: 8px;
	left: 8px;
	display: flex;
	align-items: center;
	justify-content: center;
	width: 28px;
	height: 28px;
	border: none;
	border-radius: var(--radius-full);
	background-color: rgba(0, 0, 0, 0.6);
	color: var(--text-on-brand-primary);
	cursor: pointer;
	z-index: 2;
	transition: background-color 150ms ease;
}

.inlineMuteButton:hover {
	background-color: rgba(0, 0, 0, 0.8);
}
