.overlay {
	width: 320px;
	border-radius: 8px;
	border: 1px solid var(--voice-surface-5);
	background-color: var(--voice-surface-3);
	padding: 1rem;
	box-shadow:
		0 20px 25px -5px var(--voice-shadow-soft),
		0 8px 10px -6px var(--voice-shadow-soft);
}

.header {
	margin-bottom: 1rem;
	display: flex;
	align-items: center;
	justify-content: space-between;
}

.headerContent {
	display: flex;
	align-items: center;
	gap: 0.5rem;
}

.title {
	font-weight: 600;
	color: var(--text-primary);
}

.closeButton {
	display: flex;
	height: 24px;
	width: 24px;
	align-items: center;
	justify-content: center;
	border-radius: 4px;
	color: var(--text-primary-muted);
	transition-duration: 150ms;
	transition-property: color, background-color, border-color, text-decoration-color, fill, stroke;
	cursor: pointer;
}

.closeButton:hover {
	background-color: var(--background-modifier-hover);
	color: var(--text-primary);
}

.content {
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.section {
	display: flex;
	flex-direction: column;
	gap: 0.5rem;
}

.sectionHeader {
	display: flex;
	align-items: center;
	gap: 0.5rem;
	font-weight: 500;
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--text-primary);
}

.sectionContent {
	margin-left: 1.5rem;
	display: flex;
	flex-direction: column;
	gap: 0.375rem;
}

.statRow {
	display: flex;
	align-items: center;
	justify-content: space-between;
	font-size: 0.875rem;
	line-height: 1.25rem;
}

.statLabel {
	color: var(--text-primary-muted);
}

.statValue {
	font-family: ui-monospace, SFMono-Regular, 'SF Mono', Consolas, 'Liberation Mono', Menlo, monospace;
	color: var(--text-primary);
}

.statValueColored {
	font-family: ui-monospace, SFMono-Regular, 'SF Mono', Consolas, 'Liberation Mono', Menlo, monospace;
	font-weight: 500;
}

.divider {
	height: 1px;
	background-color: var(--voice-surface-5);
}

.dividerTop {
	margin-top: 1rem;
	border-top: 1px solid var(--voice-surface-5);
	padding-top: 1rem;
}

.footerText {
	text-align: center;
	color: var(--text-primary-muted);
	font-size: 0.75rem;
	line-height: 1rem;
}

.textGreen {
	color: var(--voice-status-success);
}

.textYellow {
	color: var(--voice-status-warning-alt);
}

.textOrange {
	color: var(--voice-status-caution);
}

.textRed {
	color: var(--voice-status-danger);
}

.iconSmall {
	height: 16px;
	width: 16px;
}

.iconMedium {
	height: 20px;
	width: 20px;
}
