.container {
	align-items: center;
	color: var(--text-primary);
}

.description {
	font-size: 0.875rem;
	line-height: 1.25rem;
	text-align: center;
	color: var(--text-primary-muted);
}

.errorBox {
	width: 100%;
	padding: 0.75rem;
	border-radius: 0.375rem;
	border: 1px solid var(--status-danger);
	background-color: rgb(from var(--status-danger) r g b / 0.1);
}

.errorText {
	font-size: 0.875rem;
	line-height: 1.25rem;
	text-align: center;
	color: var(--status-danger);
}

.captchaContainer {
	display: flex;
	width: 100%;
	justify-content: center;
	margin-bottom: 1rem;
}

.switchContainer {
	text-align: center;
}

.switchButton {
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--text-link);
	text-decoration: underline;
	cursor: pointer;
}

.switchButton:hover {
	color: var(--text-link);
}

.switchButton:disabled {
	cursor: not-allowed;
	opacity: 0.5;
}
