.content {
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.warningBox {
	border-radius: 0.375rem;
	border: 1px solid var(--background-header-secondary);
	padding: 1rem;
}

.warningText {
	font-size: 0.875rem;
	color: var(--text-primary);
}

.footer {
	display: flex;
	flex-wrap: wrap;
	gap: 0.5rem;
}

.footer > * {
	flex: 1;
	min-width: fit-content;
}
