.container {
	display: flex;
	flex-direction: column;
	gap: 3rem;
}

.section {
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.sectionTitle {
	font-weight: 600;
	font-size: 1.125rem;
	line-height: 1.75rem;
}

.sectionDescription {
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--text-primary-muted);
}

.sectionDescriptionMultiline {
	font-size: 0.875rem;
	line-height: 1.25rem;
	color: var(--text-primary-muted);
}

.sectionDescriptionMultiline p {
	margin-bottom: 0.5rem;
}

.sectionDescriptionMultiline p:last-child {
	margin-bottom: 0;
}
