.sectionContent {
	margin-top: 0.5rem;
}

.previewContainer {
	margin-bottom: 1.5rem;
	display: flex;
	flex-direction: column;
	gap: 1rem;
}

.previewBox {
	border-radius: 0.5rem;
	border: 1px solid var(--background-modifier-accent);
	background-color: var(--background-secondary-lighter);
	padding-left: 1.5rem;
	padding-right: 1.5rem;
	padding-top: 2rem;
	padding-bottom: 2rem;
}

.shiftHint {
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 0.5rem;
}

.shiftHintDisabled {
	opacity: 0.4;
}

.shiftHintText {
	font-size: 0.8125rem;
	line-height: 1.4;
	color: var(--text-tertiary);
}
