.container {
	display: flex;
	flex-direction: column;
	align-items: center;
	text-align: center;
	justify-content: center;
	gap: var(--spacing-3);
	padding: var(--spacing-4);
	background: var(--background-secondary);
	border-radius: var(--radius-xl);
	min-height: 200px;
	box-shadow: none;
}

.fullHeight {
	min-height: 320px;
}

.icon {
	width: 60px;
	height: 60px;
	color: var(--text-muted);
}

.title {
	margin: 0;
	font-size: 1.3rem;
	font-weight: 600;
	color: var(--text-primary);
}

.description {
	margin: 0;
	color: var(--text-primary-muted);
	max-width: 32rem;
}

.actions {
	display: flex;
	gap: var(--spacing-3);
	flex-wrap: wrap;
	justify-content: center;
	margin-top: var(--spacing-2);
}
