.voiceChannelContainer {
	height: 100%;
	width: 100%;
}

.channelGrid {
	display: grid;
	height: 100%;
	min-height: 0;
	width: 100%;
	max-width: 100%;
	min-width: 0;
	grid-template-rows: 4rem minmax(0, 1fr);
	background: var(--background-secondary-lighter);
	overflow: hidden;
}

@media (min-width: 768px) {
	.channelGrid {
		grid-template-rows: 3.5rem minmax(0, 1fr);
	}
}

.channelGridVoiceCallActive {
	grid-template-rows: auto minmax(0, 1fr);
	background: #000;
}

@media (min-width: 768px) {
	.channelGridVoiceCallActive {
		grid-template-rows: auto minmax(0, 1fr);
	}
}

.voiceActiveHeaderWrapper {
	background-color: #000;
}

.channelGridVoiceCallActive .contentGrid {
	background: #000;
}

.contentGrid {
	display: grid;
	height: 100%;
	min-height: 0;
	width: 100%;
	max-width: 100%;
	min-width: 0;
	grid-template-columns: minmax(0, 1fr) auto;
	position: relative;
	contain: layout style;
	overflow: hidden;
}

.memberListDivider {
	position: absolute;
	top: 0;
	bottom: 0;
	right: var(--member-list-width, 16.5rem);
	width: 1px;
	background: var(--user-area-divider-color);
	pointer-events: none;
	z-index: 5;
}

.searchPanel {
	display: flex;
	height: 100%;
	min-height: 0;
	width: 100%;
	min-width: 0;
	border-left: 1px solid var(--user-area-divider-color);
}

.emptyStateContent {
	display: flex;
	height: 100%;
	width: 100%;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	gap: 1rem;
	padding: 2rem;
}

.centeredText {
	text-align: center;
}

.voiceChannelTitle {
	margin-bottom: 0.5rem;
	font-weight: 600;
	font-size: 1.5rem;
	line-height: 2rem;
	color: var(--text-primary);
}

.voiceChannelDescription {
	color: var(--text-primary-muted);
}

.buttonContainer {
	display: flex;
	flex-direction: column;
	align-items: center;
	gap: 0.75rem;
}
