.container {
	display: flex;
	align-items: center;
	gap: 4px;
	font-family: var(--font-mono, monospace);
	font-size: 12px;
	color: var(--text-secondary);
	white-space: nowrap;
	user-select: none;
	-webkit-user-select: none;
}

.time {
	min-width: 32px;
	text-align: center;
}

.separator {
	opacity: 0.7;
}

.small {
	font-size: 11px;
}

.small .time {
	min-width: 28px;
}

.medium {
	font-size: 12px;
}

.large {
	font-size: 14px;
}

.large .time {
	min-width: 40px;
}

.compact .separator,
.compact .duration {
	display: none;
}
