.menuItem {
	display: grid;
	grid-template-columns: 1fr auto;
	align-items: center;
	gap: 12px;
	padding: 8px 10px;
	margin: 0;
	border-radius: 4px;
	color: var(--text-primary);
	font-size: 14px;
	font-weight: 500;
	line-height: 18px;
	cursor: pointer;
	outline: none;
	transition: none;
	box-sizing: border-box;
	min-height: 36px;
}

.menuItem:is(:hover, [data-hovered], [data-focus-visible]):not([data-disabled]):not(.disabled) {
	background-color: var(--background-modifier-hover);
	color: var(--text-primary);
}

.menuItem.danger {
	color: var(--status-danger);
}

.menuItem.danger:is(:hover, [data-hovered], [data-focus-visible], [data-open]):not([data-disabled]):not(.disabled) {
	background-color: var(--button-danger-fill);
	color: var(--button-danger-text);
}

.menuItem[data-disabled],
.menuItem.disabled {
	color: var(--interactive-muted);
	cursor: not-allowed;
}

.icon {
	display: flex;
	align-items: center;
	justify-content: center;
	width: 20px;
	height: 20px;
	flex-shrink: 0;
	grid-column: 2;
}

.icon > svg {
	width: 20px;
	height: 20px;
	display: block;
	flex-shrink: 0;
}

.labelContainer {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
}

.label {
	white-space: nowrap;
	overflow: hidden;
	text-overflow: ellipsis;
	display: flex;
	align-items: center;
	min-height: 18px;
}

.hint {
	margin-left: 8px;
	color: var(--text-tertiary-muted);
	font-size: 12px;
	font-weight: 400;
	flex-shrink: 0;
}

.subtext {
	color: var(--text-tertiary-muted);
	font-size: 12px;
	font-weight: 400;
	line-height: 16px;
	margin-top: 2px;
}

.shortcut {
	color: var(--text-tertiary-muted);
	font-size: 12px;
	font-weight: 500;
	font-family: var(--font-mono);
	white-space: nowrap;
	flex-shrink: 0;
	--keybind-hint-background: var(--background-secondary);
	--keybind-hint-color: var(--text-secondary);
}

.menuItem:not(.danger):is(:hover, [data-hovered], [data-focus-visible], [data-open]):not([data-disabled]):not(.disabled)
	.shortcut {
	--keybind-hint-background: color-mix(in srgb, var(--background-modifier-hover) 70%, var(--background-secondary) 30%);
}

.menuItem.danger:is(:hover, [data-hovered], [data-focus-visible], [data-open]):not([data-disabled]):not(.disabled)
	.shortcut {
	--keybind-hint-background: var(--button-danger-text);
	--keybind-hint-color: var(--control-button-danger-text);
	color: var(--button-danger-text);
}

.sliderItem {
	display: flex;
	flex-direction: column;
	align-items: flex-start;
	gap: 6px;
	padding: 8px 8px;
	margin: 0;
	border-radius: 3px;
	color: var(--text-primary);
	font-size: 14px;
	font-weight: 500;
	line-height: 18px;
	cursor: default;
	outline: none;
	box-sizing: border-box;
}

.sliderItem.disabled {
	color: var(--interactive-muted);
	cursor: not-allowed;
	opacity: 0.5;
}

.sliderHeader {
	display: flex;
	width: 100%;
	align-items: center;
	justify-content: space-between;
}

.sliderLabel {
	font-size: 14px;
	font-weight: 500;
	color: currentColor;
}

.sliderValue {
	font-size: 12px;
	font-weight: 400;
	color: var(--text-tertiary-muted);
}

.sliderContainer {
	width: 100%;
}
