.header {
	display: flex;
	align-items: center;
	justify-content: space-between;
}

.headerTitle {
	margin-bottom: 0;
	font-weight: 600;
	font-size: 1rem;
}

.sliderContainer {
	margin-left: 1rem;
	display: flex;
	flex-direction: column;
	gap: 0.75rem;
}

.sliderLabel {
	display: flex;
	flex-direction: column;
	gap: 0.25rem;
}

.labelText {
	display: block;
	font-weight: 500;
	font-size: 0.875rem;
}

.labelDescription {
	margin-bottom: 0.5rem;
	color: var(--text-primary-muted);
	font-size: 0.875rem;
}

.note {
	color: var(--text-primary-muted);
	font-size: 0.75rem;
}

.buttonRow {
	display: flex;
	align-items: flex-start;
}
